// One Adzuna query per search term x location (local radius + remote keyword).
const c = $input.first().json;
const base = {
  max_days_old: c.max_days_old,
  results_per_page: c.results_per_page,
  sort_by: 'date',
  'content-type': 'application/json',
};

const items = [];
for (const term of c.search_terms) {
  items.push({ json: {
    search_term: term,
    search_type: 'local',
    query: { ...base, what: term, where: c.local_area, distance: c.distance_km },
  }});
  items.push({ json: {
    search_term: term,
    search_type: 'remote',
    query: { ...base, what: `${term} remote` },
  }});
}
return items;

// Normalise Adzuna results into the shared job shape used by every source.
const clean = (s) => String(s ?? '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&nbsp;/g, ' ')
  .replace(/&hellip;/g, '…').replace(/&ndash;/g, '–').replace(/&mdash;/g, '—').replace(/&pound;/g, '£')
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/\s+/g, ' ')
  .trim();

const gbp = (n) => '£' + Math.round(n).toLocaleString('en-GB');
const formatSalary = (r) => {
  const { salary_min: min, salary_max: max } = r;
  if (!min && !max) return '';
  const range = min && max && min !== max ? `${gbp(min)}–${gbp(max)}` : gbp(min || max);
  return String(r.salary_is_predicted) === '1' ? `${range} (est.)` : range;
};

const out = [];
for (const item of $input.all()) {
  for (const r of item.json.results ?? []) {
    out.push({ json: {
      job_id: `adzuna_${r.id}`,
      source: 'adzuna',
      title: clean(r.title),
      company: clean(r.company?.display_name),
      location: clean(r.location?.display_name),
      salary: formatSalary(r),
      url: r.redirect_url ?? '',
      description: clean(r.description),
      posted: r.created ?? '',
    }});
  }
}
return out;

// Keep only jobs not already in the sheet: same job_id, or same title + company
// (catches the same job listed on both Adzuna and Reed on different days).
const dedupKey = j => `${j.title ?? ''}|${j.company ?? ''}`
  .toLowerCase().replace(/[^a-z0-9|]+/g, ' ').replace(/\s+/g, ' ').trim();
const rows = $('Read existing jobs').all().map(i => i.json);
const seenIds = new Set(rows.map(r => String(r.job_id ?? '').trim()).filter(Boolean));
const seenKeys = new Set(rows.filter(r => r.title).map(dedupKey));
return $('Remove duplicates in run').all()
  .filter(i => !seenIds.has(i.json.job_id) && !seenKeys.has(i.json.dedup_key));

// Drop roles that are clearly too senior before spending LLM tokens on them.
const patterns = $('Search config').first().json.exclude_title_patterns ?? [];
const escape = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const re = patterns.length
  ? new RegExp('\\b(' + patterns.map(escape).join('|') + ')\\b', 'i')
  : null;
return $input.all().filter(i => !(re && re.test(i.json.title ?? '')));

// Cost cap: score at most max_jobs_per_run jobs per run.
const max = $('Search config').first().json.max_jobs_per_run ?? 40;
return $input.all().slice(0, max);

// Build one Claude Messages API request per job.
// Structured outputs (output_config.format) make the response match the schema.
const cfg = $('Search config').first().json;

const SYSTEM_PROMPT = `You are a recruitment screening assistant. You compare one job listing against one
candidate profile and return ONLY valid JSON, no prose, no code fences.

Scoring guide:
- 80–100: strong fit on core skills, level and location/remote
- 60–79: good fit with 1–2 learnable gaps
- 40–59: partial fit, several gaps
- 0–39: poor fit or wrong seniority/location

Rules:
- Judge only on the information given. Do not invent requirements.
- If salary is missing, do not penalise.
- Penalise roles requiring 5+ years in a specific tool, people-management of large
  teams, or on-site work more than 30 miles from Malvern, UK.
- Prefer hands-on automation/building roles over pure change-management roles.
- matched_skills and missing_skills: up to 6 short strings each.
- reason: one sentence, max 25 words.`;

const SCHEMA = {
  type: 'object',
  properties: {
    score: { type: 'integer', description: 'Match score 0-100' },
    matched_skills: { type: 'array', items: { type: 'string' } },
    missing_skills: { type: 'array', items: { type: 'string' } },
    seniority_fit: { type: 'string', enum: ['junior', 'mid', 'senior', 'unclear'] },
    remote_or_local_ok: { type: 'boolean' },
    reason: { type: 'string' },
  },
  required: ['score', 'matched_skills', 'missing_skills', 'seniority_fit', 'remote_or_local_ok', 'reason'],
  additionalProperties: false,
};

return $input.all().map(i => {
  const j = i.json;
  const userMessage = [
    'CANDIDATE PROFILE:',
    cfg.candidate_profile,
    '',
    'JOB LISTING:',
    `Title: ${j.title}`,
    `Company: ${j.company || 'Not stated'}`,
    `Location: ${j.location || 'Not stated'}`,
    `Salary: ${j.salary || 'Not stated'}`,
    'Description:',
    j.description || 'Not provided',
  ].join('\n');

  return { json: {
    ...j,
    claude_request: {
      model: cfg.model,
      max_tokens: 2000,
      system: SYSTEM_PROMPT,
      output_config: { effort: 'low', format: { type: 'json_schema', schema: SCHEMA } },
      messages: [{ role: 'user', content: userMessage }],
    },
  }};
});

// Parse and validate each Claude response. One bad response never breaks the run:
// it falls back to score = null with the reason recorded.
const jobs = $('Build Claude request').all();

const fallback = (why) => ({
  score: null, matched_skills: [], missing_skills: [],
  seniority_fit: 'unclear', remote_or_local_ok: null, reason: `parse error: ${why}`,
});

const parse = (resp) => {
  if (!resp || resp.error) {
    const e = resp?.error;
    return fallback(typeof e === 'string' ? e : (e?.message ?? 'request failed'));
  }
  if (resp.stop_reason === 'refusal') return fallback('model refused');
  if (resp.stop_reason === 'max_tokens') return fallback('response cut off');
  const text = (resp.content ?? []).find(b => b.type === 'text')?.text;
  if (!text) return fallback('no text in response');
  let data;
  try {
    data = JSON.parse(text.replace(/^\s*```(?:json)?\s*|\s*```\s*$/g, ''));
  } catch (e) {
    return fallback('invalid JSON');
  }
  if (!Number.isInteger(data.score) || data.score < 0 || data.score > 100) {
    return fallback('score not an integer 0-100');
  }
  const list = (a) => (Array.isArray(a) ? a.map(String).slice(0, 6) : []);
  return {
    score: data.score,
    matched_skills: list(data.matched_skills),
    missing_skills: list(data.missing_skills),
    seniority_fit: data.seniority_fit ?? 'unclear',
    remote_or_local_ok: typeof data.remote_or_local_ok === 'boolean' ? data.remote_or_local_ok : null,
    reason: String(data.reason ?? '').trim(),
  };
};

return $input.all().map((item, idx) => {
  const { claude_request, ...job } = jobs[idx]?.json ?? {};
  const resp = item.json;
  return { json: {
    ...job,
    ...parse(resp),
    input_tokens: resp?.usage?.input_tokens ?? 0,
    output_tokens: resp?.usage?.output_tokens ?? 0,
  }};
});

// Build the daily HTML digest: top 5 new jobs scoring >= 60, plus run stats.
const jobs = $('Parse score').all().map(i => i.json);
const MIN_SCORE = 60, TOP_N = 5;
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const top = jobs
  .filter(j => Number.isInteger(j.score) && j.score >= MIN_SCORE)
  .sort((a, b) => b.score - a.score)
  .slice(0, TOP_N);

const scored = jobs.filter(j => Number.isInteger(j.score)).length;
const failed = jobs.length - scored;
const inTok = jobs.reduce((s, j) => s + (j.input_tokens || 0), 0);
const outTok = jobs.reduce((s, j) => s + (j.output_tokens || 0), 0);
// claude-haiku-5-5: $0.10 per 1M input tokens, $0.50 per 1M output tokens.
const costUsd = (inTok * 0.10 + outTok * 0.50) / 1e6;
const day = $now.setZone('Europe/London').toFormat('ccc d LLL');

const card = j => `
  <tr><td style="padding:12px 0;border-bottom:1px solid #e5e5e5">
    <div style="font-size:16px"><b>${j.score}</b> &middot; ${/^https?:\/\//i.test(j.url ?? '') ? `<a href="${esc(j.url)}">${esc(j.title)}</a>` : esc(j.title)}</div>
    <div style="color:#555">${esc(j.company || 'Company not stated')} &middot; ${esc(j.location)}${j.salary ? ' &middot; ' + esc(j.salary) : ''}</div>
    <div style="margin-top:4px">${esc(j.reason)}</div>
    <div style="margin-top:4px;color:#2e7d32">✔ ${esc(j.matched_skills.join(', ') || '–')}</div>
    <div style="color:#c62828">✘ ${esc(j.missing_skills.join(', ') || '–')}</div>
  </td></tr>`;

const body = top.length
  ? `<table style="width:100%;border-collapse:collapse">${top.map(card).join('')}</table>`
  : `<p>No new jobs scored ${MIN_SCORE} or more today.</p>`;

const calls = name => { try { return $(name).all(); } catch (e) { return []; } };
const srcNote = [['Adzuna', 'Adzuna search'], ['Reed', 'Reed search']].map(([label, name]) => {
  const c = calls(name), failedCalls = c.filter(i => i.json.error).length;
  const n = jobs.filter(j => j.source === label.toLowerCase()).length;
  return `${label}: ${n} new${failedCalls ? ` (${failedCalls}/${c.length} requests failed)` : ''}`;
}).join(' · ');

const html = `<div style="font-family:Arial,sans-serif;max-width:640px">
  <h2 style="margin-bottom:4px">Job digest – ${esc(day)}</h2>
  <div style="color:#555">${jobs.length} new jobs · ${scored} scored${failed ? ` · ${failed} failed to score` : ''} · ${top.length} at ${MIN_SCORE}+</div>
  ${body}
  <p style="color:#888;font-size:12px">${esc(srcNote)}<br>Tokens: ${inTok} in / ${outTok} out · est. cost $${costUsd.toFixed(4)} · full list in the Job Tracker sheet.</p>
</div>`;

const subject = top.length
  ? `Job digest: ${top.length} match${top.length > 1 ? 'es' : ''} (top ${top[0].score}) – ${day}`
  : `Job digest: no strong matches – ${day}`;

return [{ json: { subject, html, jobs_new: jobs.length, jobs_scored: scored, matches: top.length, input_tokens: inTok, output_tokens: outTok, cost_usd: costUsd } }];

// One Reed query per search term x location (local radius in miles + remote keyword).
const c = $('Search config').first().json;
const base = { resultsToTake: c.reed_results ?? 100 };
const items = [];
for (const term of c.search_terms) {
  items.push({ json: { search_term: term, search_type: 'local',
    query: { ...base, keywords: term, locationName: c.local_area, distanceFromLocation: c.reed_distance_miles ?? 30 } } });
  items.push({ json: { search_term: term, search_type: 'remote',
    query: { ...base, keywords: `${term} remote` } } });
}
return items;

// Normalise Reed results into the shared job shape.
// Reed has no "posted since" filter, so drop listings older than reed_max_age_days here.
const clean = (s) => String(s ?? '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&nbsp;/g, ' ')
  .replace(/&hellip;/g, '…').replace(/&ndash;/g, '–').replace(/&mdash;/g, '—').replace(/&pound;/g, '£')
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/\s+/g, ' ')
  .trim();

const gbp = (n) => '£' + Math.round(n).toLocaleString('en-GB');
const formatSalary = (r) => {
  const { salary_min: min, salary_max: max } = r;
  if (!min && !max) return '';
  const range = min && max && min !== max ? `${gbp(min)}–${gbp(max)}` : gbp(min || max);
  return String(r.salary_is_predicted) === '1' ? `${range} (est.)` : range;
};

const maxAge = $('Search config').first().json.reed_max_age_days ?? 2;
const cutoff = $now.setZone('Europe/London').minus({ days: maxAge }).toFormat('yyyy-MM-dd');
const isoDate = s => {
  const m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(String(s ?? '').trim());
  return m ? `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}` : '';
};
const reedSalary = r => {
  const min = r.minimumSalary, max = r.maximumSalary;
  if (!min && !max) return '';
  const range = min && max && min !== max ? `${gbp(min)}–${gbp(max)}` : gbp(min || max);
  return (max || min) < 1000 ? `${range} (rate)` : range; // small numbers are day/hour rates
};

const out = [];
for (const item of $input.all()) {
  for (const r of item.json.results ?? []) {
    const posted = isoDate(r.date);
    if (posted && posted < cutoff) continue;
    const id = r.jobId ?? r.JobId;
    if (!id) continue;
    out.push({ json: {
      job_id: `reed_${id}`,
      source: 'reed',
      title: clean(r.jobTitle),
      company: clean(r.employerName),
      location: clean(r.locationName),
      salary: reedSalary(r),
      url: r.jobUrl || `https://www.reed.co.uk/jobs/${id}`,
      description: clean(r.jobDescription),
      posted,
    }});
  }
}
return out;

// Check source health and add a cross-source de-dup key (Adzuna also lists Reed jobs).
// Fails the run (-> error alert) only if every request to every source failed.
const dedupKey = j => `${j.title ?? ''}|${j.company ?? ''}`
  .toLowerCase().replace(/[^a-z0-9|]+/g, ' ').replace(/\s+/g, ' ').trim();
const calls = name => { try { return $(name).all(); } catch (e) { return []; } };
const sources = { Adzuna: calls('Adzuna search'), Reed: calls('Reed search') };
const down = Object.entries(sources).filter(([, c]) => c.length && c.every(i => i.json.error));
if (down.length === Object.keys(sources).length) {
  const first = down[0][1][0].json.error;
  throw new Error('All job sources failed. First error: ' + (typeof first === 'string' ? first : first?.message ?? 'unknown'));
}
return $input.all()
  .filter(i => i.json.job_id)
  .map(i => ({ json: { ...i.json, dedup_key: dedupKey(i.json) } }));
